// Safety text — Persian (fa). The Emergency situation guides and the first-aid steps, which are data (js/data/emergency.js, firstaid.js).
//
// Lazy: js/i18n.js ensureSafetyText() imports this file only when #sos, #firstaid or #hospital opens in this language, and merges the entries
// into the active dictionary, so the DOM pass finds them by exact English text (the same keys as js/data/ui-strings.fa.js, a leading emoji
// left off). Never import it from an eager module. Machine-made, every entry listed in scripts/ui-strings-review.json (source: safety-text)
// for a native review; written by tools/lang-check/safety-text.py. A string with no entry shows English.

export const SAFETY_STRINGS = {
  'Road or scooter accident': 'تصادف جاده‌ای یا اسکوتر',
  'By far the most likely serious emergency a traveller faces in this region.': 'این، با اختلاف، محتمل‌ترین وضعیت اورژانسی جدی است که یک مسافر در این منطقه با آن روبه‌رو می‌شود.',
  'Get out of the traffic lane before anything else. Being hit a second time is a real risk on a fast road, and it is what turns a survivable crash into a fatal one.': 'پیش از هر کار دیگر از مسیر عبور خودروها خارج شوید. برخورد دوم در جادهٔ پرسرعت خطری واقعی است و همان چیزی است که تصادفی قابل‌بقا را کشنده می‌کند.',
  'Call the national emergency number. Say the road, the direction of travel and the nearest landmark or kilometre marker — a screenshot of your map pin is the fastest way to answer "where are you?".': 'با شمارهٔ اضطراری کشور تماس بگیرید. نام جاده، جهت حرکت و نزدیک‌ترین نشانه یا تابلوی کیلومتر را بگویید — عکس صفحهٔ نمایش پین نقشه سریع‌ترین راه برای پاسخ به «کجایید؟» است.',
  'Do not move anyone who has hit their head or complains of neck or back pain, unless leaving them is more dangerous than moving them.': 'کسی را که سرش ضربه خورده یا از درد گردن یا کمر شکایت دارد جابه‌جا نکنید، مگر آنکه ماندنش خطرناک‌تر از جابه‌جایی باشد.',
  'Control heavy bleeding with firm, continuous pressure through whatever cloth you have. Keep pressing; do not lift to check.': 'خونریزی شدید را با فشار محکم و پیوسته روی هر پارچه‌ای که دارید مهار کنید. به فشار دادن ادامه دهید؛ برای بررسی آن را برندارید.',
  'Go to hospital even if you feel fine. Head injuries and internal bleeding declare themselves hours later, and road rash here infects fast in the heat.': 'حتی اگر حال‌تان خوب است به بیمارستان بروید. آسیب سر و خونریزی داخلی ساعتی بعد خود را نشان می‌دهند و خراشیدگی‌های ناشی از جاده در این گرما سریع عفونی می‌شوند.',
  'Get a police report. Without one, most travel insurance and every vehicle claim is disputed. Ask for the report number before you leave.': 'گزارش پلیس بگیرید. بدون آن بیشتر بیمه‌های مسافرتی و همهٔ ادعاهای خودرو مورد اختلاف قرار می‌گیرند. پیش از رفتن شمارهٔ گزارش را بخواهید.',
  'Photograph everything at the scene: both vehicles, the road, the position, any licence and registration, and the other rider. Photographs settle later arguments that memory cannot.': 'از همه‌چیز در صحنه عکس بگیرید: هر دو وسیله، جاده، موقعیت، هر گواهینامه و مدرک ثبت وسیله و راکب دیگر. عکس‌ها اختلاف‌هایی را که حافظه نمی‌تواند حل کند، فیصله می‌دهند.',
  'Tell your insurer the same day. Many policies exclude motorcycle injury unless you hold a licence valid for that engine size and were wearing a helmet — know which before you rent, not after you crash.': 'همان روز به بیمه‌گر خود اطلاع دهید. بسیاری از بیمه‌نامه‌ها آسیب موتورسیکلت را مستثنا می‌کنند مگر گواهینامهٔ معتبر برای آن حجم موتور داشته باشید و کلاه ایمنی بر سر داشته باشید — پیش از اجاره بدانید، نه پس از تصادف.',
  'Do not hand over your passport as security to a rental shop, a hospital or anyone at the scene. Offer a photocopy or a deposit instead — a withheld passport is the standard lever in a rental dispute.': 'گذرنامهٔ خود را به‌عنوان وثیقه به مغازهٔ اجاره، بیمارستان یا هیچ‌کس در صحنه ندهید. به‌جای آن فتوکپی یا ودیعه پیشنهاد کنید — نگه‌داشتن گذرنامه ابزار رایج فشار در اختلاف اجاره است.',
  'Do not agree a cash settlement at the roadside before you know the extent of your own injuries.': 'پیش از آنکه از وسعت آسیب‌های خود باخبر شوید، در کنار جاده با تسویهٔ نقدی موافقت نکنید.',
  'Drink spiking & methanol poisoning': 'مسموم‌سازی نوشیدنی و مسمومیت با متانول',
  'Rare but not hypothetical — and methanol poisoning is survivable only if it is recognised early.': 'نادر است اما فرضی نیست — و مسمومیت با متانول تنها در صورتی قابل‌بقاست که زود شناسایی شود.',
  'Treat sudden severe drunkenness that does not match how much was drunk as an emergency, especially after free shots, mixed spirits or home-made liquor.': 'مستی ناگهانی و شدید را که با مقدار نوشیدن نمی‌خواند اورژانس بدانید، به‌ویژه پس از شات رایگان، مشروبات الکلی مخلوط یا نوشیدنی خانگی.',
  'Methanol poisoning classically appears 6–30 hours after drinking, not immediately: blurred or snowy vision, severe stomach pain, breathlessness, confusion. Any vision change after drinking spirits is a hospital emergency that night, not in the morning.': 'مسمومیت با متانول معمولاً ۶ تا ۳۰ ساعت پس از نوشیدن پدیدار می‌شود، نه فوراً: تاری یا «برف‌زدگی» دید، درد شدید معده، تنگی نفس، گیجی. هر تغییر در دید پس از نوشیدن مشروبات الکلی همان شب اورژانس بیمارستانی است، نه صبح.',
  'Get the person to the largest hospital you can reach and say the words "possible methanol poisoning". Treatment exists and works; delay is what kills.': 'فرد را به بزرگ‌ترین بیمارستانی که می‌توانید برسانید و عبارت «مشکوک به مسمومیت با متانول» را بگویید. درمان وجود دارد و اثر می‌کند؛ تأخیر است که می‌کشد.',
  'If someone is unconscious but breathing, put them on their side so they cannot choke, and stay with them.': 'اگر کسی بیهوش است اما نفس می‌کشد، او را به پهلو بخوابانید تا خفه نشود و کنارش بمانید.',
  'Keep the bottle, the glass or the receipt if you safely can — it helps the hospital and any investigation.': 'اگر با ایمنی ممکن است بطری، لیوان یا رسید را نگه دارید — به بیمارستان و هر تحقیقی کمک می‌کند.',
  'Report it to the tourist police and to your embassy. Clusters are how these venues get shut.': 'به پلیس گردشگری و سفارت خود گزارش دهید. خوشه‌های موارد همان چیزی است که این مکان‌ها را بسته می‌کند.',
  'Do not let anyone "sleep it off" alone in a room. Almost every death in a spiking or methanol cluster involves someone left to sleep.': 'نگذارید کسی «بخوابد تا بگذرد» آن هم تنها در اتاق. تقریباً هر مرگی در خوشه‌های مسموم‌سازی یا متانول شامل کسی است که او را تنها خوابیده‌اند.',
  'Do not accept drinks from a shared jug or a bucket you did not watch being poured, and do not leave a drink unattended.': 'نوشیدنی از پارچ مشترک یا سطلی که ریختنش را ندیده‌اید نپذیرید و نوشیدنی خود را بی‌مراقب نگذارید.',
  'Lost or stolen passport': 'گذرنامهٔ گمشده یا سرقت‌شده',
  'Recoverable, but the order of the steps decides whether it takes two days or two weeks.': 'قابل‌بازیابی است، اما ترتیب مراحل تعیین می‌کند دو روز طول بکشد یا دو هفته.',
  'Report it to the local police and get a written report with a reference number. Every embassy asks for it, and so does your insurer.': 'به پلیس محلی گزارش دهید و گزارش کتبی با شمارهٔ ارجاع بگیرید. هر سفارتی آن را می‌خواهد و بیمه‌گر شما نیز.',
  'Contact your embassy or consulate — the nearest one is usually in Bangkok, Hanoi, Ho Chi Minh City or Phnom Penh, and many countries have none at all in Laos.': 'با سفارت یا کنسولگری خود تماس بگیرید — نزدیک‌ترین معمولاً در بانکوک، هانوی، هوشی‌مین‌سیتی یا پنوم‌پن است و بسیاری از کشورها اصلاً در لائوس نمایندگی ندارند.',
  'If your visa or entry stamp was in it, immigration will need to reissue the record before you can leave the country. Start that on the same day.': 'اگر ویزا یا مهر ورود در آن بود، اداره مهاجرت باید پیش از خروج از کشور، سابقه را دوباره صادر کند. همان روز شروع کنید.',
  'Ask for an emergency travel document if you have a flight soon; a full replacement passport takes longer and may have to be issued from a regional hub.': 'اگر به‌زودی پرواز دارید سند مسافرتی اضطراری بخواهید؛ گذرنامهٔ جایگزین کامل زمان بیشتری می‌برد و ممکن است از یک مرکز منطقه‌ای صادر شود.',
  'Cancel and replace any cards that went with it, and change the passwords for anything that was unlocked on a stolen phone.': 'کارت‌هایی را که همراهش بود ابطال و جایگزین کنید و رمز هر چیزی را که روی گوشی سرقت‌شده باز بود تغییر دهید.',
  'Do not leave the country by land while the entry record is unresolved — an unmatched entry stamp turns a lost passport into an immigration problem.': 'تا زمانی که سابقهٔ ورود حل نشده از راه زمینی از کشور خارج نشوید — مهر ورود بی‌تطابق، گم‌شدن گذرنامه را به مشکل مهاجرتی تبدیل می‌کند.',
  'Do not rely on the photocopy alone. Keep a photograph of the data page and the entry stamp somewhere you can reach without your phone.': 'تنها به فتوکپی تکیه نکنید. عکس صفحهٔ مشخصات و مهر ورود را جایی نگه دارید که بدون گوشی به آن دسترسی داشته باشید.',
  'Robbery, theft or assault': 'سرقت مسلحانه، دزدی یا حمله',
  'Snatch theft from a moving motorbike is the common version, and it injures people because they hold on.': 'کیف‌قاپی از موتورسیکلت در حال حرکت رایج‌ترین شکل است و مردم را زخمی می‌کند چون کیف را محکم نگه می‌دارند.',
  'Let it go. A bag is replaceable; being dragged along a road is how snatch theft causes serious injury and death.': 'رهایش کنید. کیف جایگزین‌پذیر است؛ کشیده‌شدن روی جاده همان چیزی است که کیف‌قاپی را به آسیب جدی و مرگ می‌رساند.',
  'If you are hurt, treat that first and go to hospital — the report can be made afterwards.': 'اگر آسیب دیده‌اید ابتدا به آن رسیدگی کنید و به بیمارستان بروید — گزارش را بعداً می‌توان داد.',
  'Report it to the tourist police where there is a tourist police unit; they usually have English speakers and handle traveller cases directly.': 'در جایی که واحد پلیس گردشگری وجود دارد به آن گزارش دهید؛ معمولاً انگلیسی‌زبان دارد و مستقیماً به پرونده‌های مسافران رسیدگی می‌کند.',
  'Freeze cards immediately and check for transactions — card cloning at ATMs is common in this region.': 'کارت‌ها را فوراً مسدود کنید و تراکنش‌ها را بررسی کنید — کپی‌برداری از کارت در خودپردازها در این منطقه رایج است.',
  'Get the written police report for your insurer; a verbal report is not enough for a claim.': 'گزارش کتبی پلیس را برای بیمه‌گر خود بگیرید؛ گزارش شفاهی برای ادعا کافی نیست.',
  'Tell your embassy if a passport, a visa or your safety is involved.': 'اگر گذرنامه، ویزا یا ایمنی شما در میان است به سفارت خود اطلاع دهید.',
  'Do not chase anyone, and do not confront a group.': 'کسی را تعقیب نکنید و با یک گروه درگیر نشوید.',
  'Do not carry your only card, your only phone and your passport in the same bag.': 'تنها کارت، تنها گوشی و گذرنامه‌تان را در یک کیف حمل نکنید.',
  'Arrested or detained': 'بازداشت یا نگه‌داری',
  'Drug offences carry severe penalties across all four countries, including sentences travellers do not expect.': 'جرایم مواد مخدر در هر چهار کشور مجازات‌های سنگینی دارد، از جمله مجازات‌هایی که مسافران انتظارشان را ندارند.',
  'Ask immediately, clearly and repeatedly to contact your embassy. You are entitled to consular access; the request is what triggers it.': 'بی‌درنگ، روشن و مکرر درخواست کنید با سفارت خود تماس بگیرید. شما حق دسترسی کنسولی دارید؛ همین درخواست آن را فعال می‌کند.',
  'Do not sign anything you cannot read, and say so plainly. Ask for a translated copy and for a lawyer.': 'چیزی را که نمی‌توانید بخوانید امضا نکنید و این را صریح بگویید. نسخهٔ ترجمه‌شده و وکیل بخواهید.',
  'Stay calm and polite. Argument and raised voices make everything that follows harder.': 'آرام و مؤدب بمانید. بحث و بالا بردن صدا هر آنچه را پس از آن می‌آید دشوارتر می‌کند.',
  'The embassy can supply a list of local lawyers, contact your family and monitor your treatment.': 'سفارت می‌تواند فهرستی از وکلای محلی بدهد، با خانوادهٔ شما تماس بگیرد و رفتار با شما را پیگیری کند.',
  'Arrange money through family or your insurer rather than through anyone who approaches you at the station.': 'پول را از طریق خانواده یا بیمه‌گر ترتیب دهید، نه از طریق کسی که در ایستگاه به شما نزدیک می‌شود.',
  'Do not offer money to a police officer. In a genuine arrest it converts a bad situation into a far worse one.': 'به افسر پلیس پول پیشنهاد نکنید. در یک بازداشت واقعی، این کار وضعیت بد را بسیار بدتر می‌کند.',
  'Do not assume a substance is legal because it is sold openly to tourists — cannabis law in Thailand has changed more than once and differs completely in the other three countries.': 'فرض نکنید ماده‌ای قانونی است فقط چون علناً به گردشگران فروخته می‌شود — قانون شاهدانه در تایلند بیش از یک بار تغییر کرده و در سه کشور دیگر کاملاً متفاوت است.',
  'In trouble in the water': 'گرفتار در آب',
  'Drowning is the second leading cause of traveller death here, and rip currents cause most of it.': 'غرق‌شدگی دومین علت مرگ مسافران در اینجاست و بیشتر آن به‌دلیل جریان‌های برگشتی است.',
  'Caught in a rip: do not swim against it. Float, signal, and swim parallel to the beach until the pull stops, then come in at an angle.': 'اگر در جریان برگشتی گرفتار شدید: خلاف آن شنا نکنید. روی آب بمانید، علامت بدهید و موازی ساحل شنا کنید تا کشش تمام شود، سپس مایل به سمت ساحل برگردید.',
  'Helping someone else: throw them something that floats and call for help. Swimming out to a panicking person is how one drowning becomes two.': 'برای کمک به دیگری: چیزی شناور به‌سمتش پرتاب کنید و کمک بخواهید. شنا کردن به‌سوی فرد وحشت‌زده همان چیزی است که یک غرق‌شدگی را دو تا می‌کند.',
  'Out of the water and not breathing: start chest compressions immediately — hard and fast in the centre of the chest, about twice a second — and send someone for an ambulance.': 'از آب بیرون آمده و نفس نمی‌کشد: بلافاصله ماساژ قلبی را شروع کنید — محکم و سریع در مرکز قفسهٔ سینه، حدود دو بار در ثانیه — و کسی را برای آمبولانس بفرستید.',
  'Anyone who has been under the water needs hospital assessment even if they seem fine afterwards.': 'هرکسی که زیر آب رفته حتی اگر پس از آن خوب به نظر برسد به ارزیابی بیمارستانی نیاز دارد.',
  'For a jellyfish sting, flood the area with vinegar for at least thirty seconds and treat any breathing difficulty as an emergency. Box jellyfish are present in the Gulf of Thailand and around the Cambodian coast.': 'برای نیش عروس دریایی، ناحیه را دست‌کم سی ثانیه با سرکه شست‌وشو دهید و هر دشواری تنفسی را اورژانس بدانید. عروس دریایی جعبه‌ای در خلیج تایلند و اطراف ساحل کامبوج وجود دارد.',
  'Do not swim where a red flag is flying, and do not judge a beach by how calm it looks — rips are strongest where the water appears flattest.': 'جایی که پرچم قرمز برافراشته است شنا نکنید و ساحل را از روی آرام‌بودنش قضاوت نکنید — جریان‌های برگشتی در جایی که آب صاف‌تر به نظر می‌رسد قوی‌ترند.',
  'Do not drink and swim, and do not swim alone at night.': 'نوشیدنی الکلی نخورید و شنا نکنید و شب تنها شنا نکنید.',
  'High fever': 'تب بالا',
  'Dengue is the biggest infectious risk to travellers in this region, and it is seasonal rather than rare.': 'تب دنگی بزرگ‌ترین خطر عفونی برای مسافران در این منطقه است و فصلی است، نه نادر.',
  'Any fever above 38 °C that lasts more than 24 hours needs a doctor and a blood test. Dengue, malaria and typhoid all start looking like flu.': 'هر تب بالای ۳۸ °C که بیش از ۲۴ ساعت طول بکشد به پزشک و آزمایش خون نیاز دارد. دنگی، مالاریا و حصبه همگی شبیه آنفلوانزا شروع می‌شوند.',
  'Take paracetamol for fever and pain — nothing else.': 'برای تب و درد پاراستامول مصرف کنید — و هیچ چیز دیگر.',
  'Drink steadily. Dehydration is what turns a manageable dengue into an admission.': 'پیوسته بنوشید. کم‌آبی همان چیزی است که دنگی قابل‌مدیریت را به بستری تبدیل می‌کند.',
  'Warning signs that mean hospital now, not tomorrow: severe stomach pain, repeated vomiting, bleeding gums or nose, black stools, breathlessness, or a sudden drop in temperature with cold clammy skin.': 'نشانه‌های هشداری که یعنی همین الان بیمارستان، نه فردا: درد شدید معده، استفراغ مکرر، خونریزی لثه یا بینی، مدفوع سیاه، تنگی نفس، یا افت ناگهانی دما با پوست سرد و چسبناک.',
  'Malaria is a risk in forested border areas rather than the cities. Tell the doctor exactly where you have been in the last month.': 'مالاریا در مناطق مرزی جنگلی خطر است، نه در شهرها. به پزشک دقیقاً بگویید در یک ماه گذشته کجا بوده‌اید.',
  'Do not take ibuprofen, aspirin or any other anti-inflammatory until dengue has been ruled out — they increase bleeding risk.': 'تا زمانی که دنگی رد نشده ایبوپروفن، آسپیرین یا هر ضدالتهاب دیگری مصرف نکنید — خطر خونریزی را افزایش می‌دهند.',
  'Do not buy antimalarials or antibiotics from a small shop; counterfeit medicine is a genuine problem outside established pharmacies.': 'داروی ضدمالاریا یا آنتی‌بیوتیک را از مغازهٔ کوچک نخرید؛ داروی تقلبی در خارج از داروخانه‌های معتبر مشکلی واقعی است.',
  'Severe stomach illness': 'بیماری شدید معده',
  'Common, usually self-limiting, and occasionally the thing that puts a traveller on a drip.': 'شایع و معمولاً خودبه‌خود برطرف‌شونده است و گاهی همان چیزی است که مسافر را به سرم می‌کشاند.',
  'Rehydrate with oral rehydration salts, sold in every pharmacy in the region. Water alone does not replace what is being lost.': 'با نمک‌های بازآبرسانی خوراکی که در هر داروخانهٔ منطقه فروخته می‌شود مایعات را جبران کنید. آب تنها جایگزین آنچه از دست می‌رود نمی‌شود.',
  'Small sips, often, are better tolerated than a glass at a time.': 'جرعه‌های کوچک و مکرر بهتر از یک لیوان یک‌جا تحمل می‌شوند.',
  'See a doctor if there is blood in the stool, a fever above 38.5 °C, vomiting that stops you keeping fluids down, or symptoms lasting more than three days.': 'در صورت وجود خون در مدفوع، تب بالای ۳۸٫۵ °C، استفراغی که نگه‌داشتن مایعات را ناممکن می‌کند یا علائمی که بیش از سه روز ادامه دارد به پزشک مراجعه کنید.',
  'A young child, an older traveller or anyone pregnant should be seen much sooner than that.': 'کودک خردسال، مسافر سالمند یا زن باردار باید خیلی زودتر ویزیت شوند.',
  'Do not take a stop-the-symptoms antidiarrhoeal if there is blood or a high fever — it can make the underlying infection worse.': 'در صورت وجود خون یا تب بالا داروی بندآورندهٔ اسهال مصرف نکنید — ممکن است عفونت زمینه‌ای را بدتر کند.',
  'Flood, storm, earthquake or tsunami': 'سیل، طوفان، زلزله یا سونامی',
  'The regional hazards are seasonal flooding, tropical storms, and — on the Andaman coast — tsunami.': 'خطرهای منطقه‌ای سیل‌های فصلی، طوفان‌های گرمسیری و در ساحل آندامان سونامی است.',
  'Feel a strong earthquake on the coast, or see the sea suddenly draw back? Move inland and uphill immediately and do not wait for an official warning. On the Andaman coast, follow the blue tsunami evacuation signs.': 'زلزلهٔ شدید در ساحل حس کردید یا دیدید دریا ناگهان عقب نشست؟ فوراً به داخل خشکی و بالاتر بروید و منتظر هشدار رسمی نمانید. در ساحل آندامان تابلوهای آبی تخلیهٔ سونامی را دنبال کنید.',
  'Flooding: never walk or drive through moving water. Thirty centimetres will float a car and knee-deep flow will take an adult off their feet. Flash floods in the northern gorges rise in minutes.': 'سیل: هرگز از میان آب روان پیاده یا با خودرو عبور نکنید. سی سانتی‌متر آب خودرو را شناور می‌کند و جریان تا زانو بزرگسال را زمین می‌زند. سیل ناگهانی در تنگه‌های شمالی در چند دقیقه بالا می‌آید.',
  'Storm: get indoors and away from windows, trees and hoardings. Boat services stop for a reason — do not press a captain to sail.': 'طوفان: به داخل ساختمان بروید و از پنجره‌ها، درختان و تابلوهای بزرگ دور شوید. خدمات قایق به دلیلی متوقف می‌شوند — ناخدا را برای حرکت تحت فشار نگذارید.',
  'Assume the water is contaminated after any flood, and treat every cut and graze that touched it.': 'پس از هر سیل فرض کنید آب آلوده است و هر بریدگی و خراشی را که با آن تماس داشته درمان کنید.',
  'Register with your embassy’s travel service if one is available, so you can be contacted during a large event.': 'اگر خدمات مسافرتی سفارت شما وجود دارد در آن ثبت‌نام کنید تا در رویداد بزرگ بتوانند با شما تماس بگیرند.',
  'Do not rely on mobile coverage during a major event; agree a meeting point with anyone you are travelling with in advance.': 'در رویداد بزرگ به آنتن‌دهی موبایل تکیه نکنید؛ از پیش با همسفران خود محل ملاقات تعیین کنید.',
  'Fire in a hotel or hostel': 'آتش‌سوزی در هتل یا هاستل',
  'Older guesthouses across the region often have one staircase, barred windows and no working alarm.': 'مهمان‌خانه‌های قدیمی‌تر در سراسر منطقه اغلب یک راه‌پله، پنجره‌های میله‌دار و آژیر ناکارآمد دارند.',
  'Get out and stay out. Do not stop for luggage.': 'بیرون بروید و بیرون بمانید. برای چمدان‌ها توقف نکنید.',
  'Stay low under smoke, and feel a door with the back of your hand before opening it.': 'زیر دود پایین بمانید و پیش از باز کردن در، آن را با پشت دست لمس کنید.',
  'If you cannot get out, close the door, block the gap with wet cloth, get to a window and make yourself visible.': 'اگر نمی‌توانید بیرون بروید، در را ببندید، شکاف را با پارچهٔ خیس مسدود کنید، به پنجره بروید و خود را قابل‌رؤیت کنید.',
  'Account for everyone you are travelling with at a point away from the building.': 'از حضور همهٔ همسفران خود در نقطه‌ای دور از ساختمان مطمئن شوید.',
  'Do not use a lift. Check where the stairs are on the night you arrive — it takes ten seconds and it is the whole of fire safety in a strange building.': 'از آسانسور استفاده نکنید. در شب ورود محل راه‌پله‌ها را بررسی کنید — ده ثانیه طول می‌کشد و کل ایمنی آتش در ساختمانی ناآشناست.',
  'Someone you are travelling with is missing': 'یکی از همسفران شما گم شده است',
  'Report it to the police immediately. There is no waiting period, and the first hours matter most.': 'فوراً به پلیس گزارش دهید. دورهٔ انتظاری وجود ندارد و ساعت‌های اول از همه مهم‌ترند.',
  'Contact your embassy at the same time — they can press a case that a local station may otherwise treat as routine.': 'هم‌زمان با سفارت خود تماس بگیرید — می‌تواند پرونده‌ای را پیگیری کند که ایستگاه محلی شاید عادی تلقی کند.',
  'Check the hospitals in the area as well as the police; someone brought in unconscious and without documents may not be identified for a while.': 'علاوه بر پلیس، بیمارستان‌های منطقه را هم بررسی کنید؛ کسی که بیهوش و بدون مدارک آورده شده ممکن است مدتی شناسایی نشود.',
  'Gather a recent photograph, what they were wearing, their phone number and any location-sharing they had switched on.': 'عکس اخیر، لباسی که پوشیده بود، شمارهٔ تلفنش و هر اشتراک‌گذاری موقعیتی را که روشن داشته جمع کنید.',
  'Ask their accommodation, their last known driver or boat operator, and the last place they were seen. Local businesses often know more than a station does.': 'از محل اقامتشان، آخرین راننده یا قایق‌ران شناخته‌شده و آخرین جایی که دیده شده‌اند بپرسید. کسب‌وکارهای محلی اغلب بیش از یک ایستگاه می‌دانند.',
  'Do not delay to "give it another day". The advice from every consular service is to report early and stand it down later if it was nothing.': 'برای «یک روز دیگر صبر کنیم» تأخیر نکنید. توصیهٔ هر دفتر کنسولی این است که زود گزارش دهید و اگر چیزی نبود بعداً لغو کنید.',
  'A mental health crisis': 'بحران روانی',
  'Long trips, isolation, heat, drink and sleeplessness make this more common on the road than at home.': 'سفرهای طولانی، انزوا، گرما، نوشیدن و بی‌خوابی این را در سفر شایع‌تر از خانه می‌کند.',
  'If someone is at immediate risk of harming themselves, do not leave them alone, and call the national emergency number.': 'اگر کسی در خطر فوری آسیب زدن به خود است او را تنها نگذارید و با شمارهٔ اضطراری کشور تماس بگیرید.',
  'Get to a hospital emergency department; the larger private hospitals in Bangkok, Ho Chi Minh City, Hanoi and Phnom Penh have psychiatric services, most public provincial hospitals do not.': 'به بخش اورژانس یک بیمارستان بروید؛ بیمارستان‌های خصوصی بزرگ در بانکوک، هوشی‌مین‌سیتی، هانوی و پنوم‌پن خدمات روان‌پزشکی دارند، بیشتر بیمارستان‌های دولتی استانی ندارند.',
  'Remove the immediate means of harm if you can do so safely.': 'اگر با ایمنی ممکن است وسیلهٔ آسیب فوری را دور کنید.',
  'Your travel insurer’s assistance line can arrange a psychiatric referral and, where needed, a medically escorted flight home.': 'خط پشتیبانی بیمه‌گر مسافرتی شما می‌تواند ارجاع روان‌پزشکی و در صورت نیاز پرواز بازگشت با همراهی پزشکی ترتیب دهد.',
  'Your embassy can contact family and help with practical arrangements.': 'سفارت شما می‌تواند با خانواده تماس بگیرد و در ترتیبات عملی کمک کند.',
  'Local mental health services are limited in Cambodia and Laos in particular; getting to a major city, or home, is often the realistic plan.': 'خدمات سلامت روان محلی به‌ویژه در کامبوج و لائوس محدود است؛ رسیدن به یک شهر بزرگ یا بازگشت به خانه اغلب برنامهٔ واقع‌بینانه است.',
  'Do not treat "they have been drinking" as an explanation that makes it less urgent.': '«مشروب خورده بودند» را توضیحی که موضوع را کم‌فوریت می‌کند تلقی نکنید.',
  'If a traveller dies': 'اگر مسافری بمیرد',
  'The hardest page here, written down so nobody has to work it out while grieving.': 'سخت‌ترین صفحهٔ اینجا، نوشته شده تا کسی مجبور نشود در سوگ خودش همه‌چیز را کشف کند.',
  'Contact your embassy or consulate first. Repatriation, local registration of the death and the paperwork all run through them, and they will explain the order of it.': 'ابتدا با سفارت یا کنسولگری خود تماس بگیرید. بازگرداندن پیکر، ثبت محلی مرگ و همهٔ کاغذبازی از طریق آن‌هاست و ترتیبش را توضیح می‌دهند.',
  'Contact the travel insurer. Repatriation of remains is expensive and is the single most valuable thing a policy covers.': 'با بیمه‌گر مسافرتی تماس بگیرید. بازگرداندن پیکر پرهزینه است و ارزشمندترین چیزی است که یک بیمه‌نامه پوشش می‌دهد.',
  'A local death certificate is issued by the authorities where the death occurred; the embassy can advise on getting it recognised at home.': 'گواهی فوت محلی را مقامات محل وقوع مرگ صادر می‌کنند؛ سفارت می‌تواند دربارهٔ به‌رسمیت‌شناخته‌شدن آن در کشور خودتان راهنمایی کند.',
  'Do not agree to a cremation or a burial before speaking to the embassy and the family — in some countries it cannot be undone or reversed.': 'پیش از گفتگو با سفارت و خانواده با سوزاندن یا دفن موافقت نکنید — در برخی کشورها نمی‌توان آن را لغو یا برگرداند.',
  'Issue an emergency travel document or a replacement passport.': 'صدور سند مسافرتی اضطراری یا گذرنامهٔ جایگزین.',
  'Contact your family and help you get money sent to you.': 'تماس با خانوادهٔ شما و کمک به دریافت پول.',
  'Visit you and monitor your treatment if you are arrested or detained.': 'ملاقات با شما و پیگیری رفتار با شما در صورت بازداشت یا نگه‌داری.',
  'Give you a list of local lawyers, translators and doctors.': 'دادن فهرستی از وکلا، مترجمان و پزشکان محلی به شما.',
  'Help in a death, a serious accident, or a large-scale emergency.': 'کمک در مورد مرگ، حادثهٔ جدی یا وضعیت اضطراری گسترده.',
  'Give you the current official travel and health advice for where you are.': 'ارائهٔ توصیه‌های رسمی و به‌روز سفر و سلامت برای جایی که هستید.',
  'Get you out of prison, or interfere in a local investigation or court case.': 'آزاد کردن شما از زندان یا مداخله در تحقیق یا پروندهٔ دادگاهی محلی.',
  'Pay your medical bills, your legal costs or your fare home.': 'پرداخت صورتحساب‌های پزشکی، هزینه‌های حقوقی یا بلیت بازگشت شما.',
  'Investigate a crime, or make the police act faster than local law allows.': 'تحقیق دربارهٔ جرم یا واداشتن پلیس به اقدام سریع‌تر از آنچه قانون محلی اجازه می‌دهد.',
  'Give you legal or medical advice of its own.': 'ارائهٔ مشورهٔ حقوقی یا پزشکی از طرف خود.',
  'Many countries have an embassy in Bangkok, Hanoi and Phnom Penh but none at all in Vientiane — in Laos your nearest consular help is often in Bangkok. Find yours, and save the address and the emergency line, before you need it.': 'بسیاری از کشورها در بانکوک، هانوی و پنوم‌پن سفارت دارند اما در وینتیان اصلاً ندارند — در لائوس نزدیک‌ترین کمک کنسولی اغلب در بانکوک است. سفارت خود را پیدا کنید و نشانی و خط اضطراری را پیش از نیاز ذخیره کنید.',
  '24h emergency': 'اورژانس ۲۴ ساعته',
  'Children': 'کودکان',
  'Maternity': 'زایمان',
  'English / international': 'انگلیسی / بین‌المللی',
  'Major trauma & surgery': 'ترومای شدید و جراحی',
  'Hyperbaric (dive) chamber': 'اتاق فشار بالا (غواصی)',
  'Arranges medical evacuation': 'تخلیهٔ پزشکی را ترتیب می‌دهد',
  'Not responding, or not breathing normally': 'بی‌پاسخ است یا طبیعی نفس نمی‌کشد',
  'Allergic reaction & breathing emergencies': 'واکنش آلرژیک و اورژانس‌های تنفسی',
  'Bleeding, shock, burns & collapse': 'خونریزی، شوک، سوختگی و فروپاشی',
  'Heart, stroke & blood sugar': 'قلب، سکته و قند خون',
  'Babies & children — everyday emergencies': 'نوزادان و کودکان — اورژانس‌های روزمره',
  'Snakes, marine life & animal bites': 'مار، جانوران دریایی و گزش حیوانات',
  'Water, weather & getting help': 'آب، آب‌وهوا و کمک گرفتن',
  'Someone collapses, or will not wake up': 'کسی از پا می‌افتد یا بیدار نمی‌شود',
  'Check for a response — speak loudly and gently shake their shoulders (a baby: tap the foot, do not shake).': 'پاسخ‌دهی را بررسی کنید — بلند صحبت کنید و شانه‌هایش را آرام تکان دهید (نوزاد: به کف پا بزنید، تکان ندهید).',
  'If they respond and are breathing normally: do not move them if you suspect a neck or back injury; otherwise put them in the recovery position (below) and keep checking their breathing.': 'اگر پاسخ می‌دهد و طبیعی نفس می‌کشد: در صورت مشکوک بودن به آسیب گردن یا کمر او را حرکت ندهید؛ وگرنه در وضعیت ریکاوری (پایین) قرار دهید و تنفسش را مدام بررسی کنید.',
  'If they do NOT respond: shout for help, and check breathing for up to 10 seconds — look, listen, feel. Noisy, gasping or irregular breathing counts as "not breathing normally".': 'اگر پاسخ نمی‌دهد: کمک بخواهید و تا ۱۰ ثانیه تنفس را بررسی کنید — ببینید، گوش دهید، حس کنید. نفس پرصدا، نفس‌نفس‌زدن یا نامنظم یعنی «طبیعی نفس نمی‌کشد».',
  'Not breathing, or not breathing normally: call the emergency number on speakerphone (or send someone to) and start CPR immediately — see the adult/child or baby steps below. Do not wait to find a pulse; lay rescuers are not asked to check for one.': 'نفس نمی‌کشد یا طبیعی نفس نمی‌کشد: با بلندگو به شمارهٔ اضطراری زنگ بزنید (یا کسی را بفرستید) و فوراً احیا (CPR) را شروع کنید — مراحل بزرگسال/کودک یا نوزاد را در پایین ببینید. منتظر یافتن نبض نمانید؛ از نجاتگران غیرحرفه‌ای انتظار بررسی آن نمی‌رود.',
  'Send someone to find an AED (defibrillator) if one might be nearby — large hotels, malls and airports sometimes have one.': 'کسی را بفرستید تا AED (دفیبریلاتور) پیدا کند اگر ممکن است نزدیک باشد — هتل‌های بزرگ، مراکز خرید و فرودگاه‌ها گاهی دارند.',
  'CPR — adult and child over about 1 year': 'احیا — بزرگسال و کودک بالای حدود یک سال',
  'Lay them on their back on a firm, flat surface.': 'او را به پشت روی سطحی محکم و صاف بخوابانید.',
  'Heel of one hand on the centre of the chest (lower half of the breastbone); for a child, one or two hands depending on their size.': 'پاشنهٔ یک دست را روی مرکز قفسهٔ سینه (نیمهٔ پایینی جناغ) بگذارید؛ برای کودک، بسته به جثه‌اش یک یا دو دست.',
  'Push hard and fast: adult depth 5–6 cm, child about one-third of the chest’s depth (roughly 5 cm) — both at 100–120 pushes per minute, letting the chest fully rise between pushes.': 'محکم و سریع فشار دهید: عمق ۵ تا ۶ سانتی‌متر برای بزرگسال، برای کودک حدود یک‌سوم عمق قفسهٔ سینه (حدود ۵ سانتی‌متر) — هر دو با ۱۰۰ تا ۱۲۰ فشار در دقیقه و بازگشت کامل قفسهٔ سینه بین فشارها.',
  'If trained and willing: 30 pushes, then 2 rescue breaths, repeating (children may be given 15:2 if there are two trained rescuers). If untrained, unwilling, or unable to give breaths: continuous push-only CPR is still far better than nothing.': 'اگر آموزش دیده و مایل هستید: ۳۰ فشار سپس ۲ تنفس نجات، و تکرار (برای کودکان در صورت وجود دو نجاتگر آموزش‌دیده ۱۵:۲ ممکن است). اگر آموزش ندیده‌اید، تمایل ندارید یا نمی‌توانید تنفس بدهید: احیای فقط با فشار مداوم باز هم بسیار بهتر از هیچ است.',
  'Use an AED the moment one arrives and follow its voice prompts — it will not shock unless a shock is needed.': 'به محض رسیدن AED از آن استفاده کنید و دستورهای صوتی‌اش را دنبال کنید — مگر آنکه شوک لازم باشد، شوک نمی‌دهد.',
  'Keep going until the person starts breathing normally, professional help takes over, or you are physically unable to continue.': 'ادامه دهید تا فرد طبیعی نفس بکشد، نیروی حرفه‌ای کار را تحویل بگیرد یا از نظر جسمی نتوانید ادامه دهید.',
  'Alone with no phone: with an adult, call first, then start CPR. With a child, current guidance is to give CPR for about one to two minutes first if you truly cannot call and compress at the same time (put the phone on speaker and start compressions the moment you have dialled, if that is possible instead).': 'تنها و بدون تلفن: برای بزرگسال، اول تماس بگیرید سپس احیا را شروع کنید. برای کودک، راهنمای فعلی این است که اگر واقعاً نمی‌توانید همزمان تماس بگیرید و فشار بدهید، ابتدا حدود یک تا دو دقیقه احیا بدهید (در صورت امکان، تلفن را روی بلندگو بگذارید و به‌محض شماره‌گیری فشارها را شروع کنید).',
  'A rescuer taught with breaths first (5 initial breaths before compressions, still taught in the UK/Europe for children) and one taught compressions-first (the US/AHA approach) are both following a currently-endorsed method — do not hesitate over which to use.': 'نجاتگری که آموزش دیده ابتدا تنفس بدهد (۵ تنفس اولیه پیش از فشار، هنوز در بریتانیا/اروپا برای کودکان آموزش داده می‌شود) و نجاتگری که ابتدا فشار بدهد (رویکرد آمریکایی/AHA) هر دو روشی را دنبال می‌کنند که اکنون تأیید شده است — در انتخاب میان آن‌ها تردید نکنید.',
  'CPR — baby under 1 year': 'احیا — نوزاد زیر یک سال',
  'Lay the baby on their back on a firm surface, head in a neutral position (not tilted back).': 'نوزاد را به پشت روی سطح محکم بخوابانید، سر در وضعیت خنثی (به عقب خم نشود).',
  'For rescue breaths, your mouth covers the baby’s mouth AND nose.': 'برای تنفس نجات، دهان شما هم دهان و هم بینی نوزاد را می‌پوشاند.',
  'Compress the lower half of the breastbone, just below the nipple line, using two thumbs wrapped around the chest (preferred where you can manage it) or the heel of one hand if you cannot encircle the chest — two fingers is also still taught in some countries and is not wrong if that is what you learned.': 'نیمهٔ پایینی جناغ را، درست زیر خط نوک پستان‌ها، با دو انگشت شست که دور قفسهٔ سینه حلقه شده فشار دهید (در صورت امکان ترجیحاً) یا با پاشنهٔ یک دست اگر نمی‌توانید دور قفسه را بگیرید — فشار با دو انگشت هنوز در برخی کشورها آموزش داده می‌شود و اگر همان را یاد گرفته‌اید اشتباه نیست.',
  'Push at least one-third of the chest’s depth (about 4 cm), 100–120 per minute.': 'دست‌کم یک‌سوم عمق قفسهٔ سینه (حدود ۴ سانتی‌متر) فشار دهید، ۱۰۰ تا ۱۲۰ بار در دقیقه.',
  '30 compressions to 2 breaths for a single rescuer; 15:2 if there are two trained rescuers.': '۳۰ فشار به ۲ تنفس برای یک نجاتگر؛ ۱۵:۲ اگر دو نجاتگر آموزش‌دیده باشند.',
  'Keep going until the baby responds, help takes over, or you cannot continue.': 'ادامه دهید تا نوزاد پاسخ دهد، کمک جای شما را بگیرد یا نتوانید ادامه دهید.',
  'Which hand technique is "correct" is genuinely still shifting between countries as of 2026 — two-thumb encircling is now preferred almost everywhere, but two-finger and heel-of-one-hand are still taught and are not mistakes.': 'اینکه کدام روش دست «درست» است تا سال ۲۰۲۶ هنوز میان کشورها واقعاً در حال تغییر است — حلقه‌کردن با دو شست اکنون تقریباً همه‌جا ترجیح داده می‌شود، اما دو انگشت و پاشنهٔ یک دست هنوز آموزش داده می‌شوند و اشتباه نیستند.',
  'Choking — adult and child over about 1 year': 'خفگی — بزرگسال و کودک بالای حدود یک سال',
  'If they can cough, speak or breathe: encourage coughing and do nothing else yet.': 'اگر می‌تواند سرفه کند، حرف بزند یا نفس بکشد: او را به سرفه تشویق کنید و فعلاً کار دیگری نکنید.',
  'If they cannot cough, speak or breathe: give up to 5 firm blows between the shoulder blades with the heel of your hand.': 'اگر نمی‌تواند سرفه کند، حرف بزند یا نفس بکشد: تا ۵ ضربهٔ محکم با پاشنهٔ دست میان کتف‌ها بزنید.',
  'Not cleared: give up to 5 abdominal thrusts — stand behind them, fist just above the navel, pull sharply inward and upward. (Some countries — Australia and New Zealand — teach chest thrusts instead of abdominal thrusts; both are recognised as effective.)': 'باز نشد: تا ۵ فشار شکمی بدهید — پشت او بایستید، مشت درست بالای ناف، محکم به داخل و بالا بکشید. (برخی کشورها — استرالیا و نیوزیلند — به‌جای فشار شکمی، فشار قفسهٔ سینه آموزش می‌دهند؛ هر دو مؤثر شناخته شده‌اند.)',
  'Keep alternating 5 back blows with 5 thrusts until the object clears or the person becomes unresponsive.': '۵ ضربهٔ پشت و ۵ فشار را به‌نوبت ادامه دهید تا جسم خارج شود یا فرد بی‌پاسخ شود.',
  'If they become unresponsive: lower them to the ground and start CPR (above) — look in the mouth each time you open the airway and only remove an object you can actually see.': 'اگر بی‌پاسخ شد: او را روی زمین بخوابانید و احیا را شروع کنید (بالا) — هر بار که راه هوایی را باز می‌کنید داخل دهان را ببینید و فقط جسمی را که واقعاً می‌بینید خارج کنید.',
  'Anyone who was given abdominal thrusts should see a doctor afterwards, even once the object is out — they can cause internal injury.': 'هر کسی که فشار شکمی دریافت کرده باید پس از آن حتی بعد از خروج جسم به پزشک مراجعه کند — این فشارها می‌توانند آسیب داخلی ایجاد کنند.',
  'Never do a blind finger sweep of the mouth.': 'هرگز با انگشت و بدون دیدن داخل دهان را نکاوید.',
  'Choking — baby under 1 year': 'خفگی — نوزاد زیر یک سال',
  'Lay the baby face down along your forearm or thigh, head lower than their chest, supporting the head and jaw.': 'نوزاد را روی شکم، در امتداد ساعد یا ران خود بگذارید، سر پایین‌تر از سینه، با حمایت از سر و فک.',
  'Give up to 5 firm back blows between the shoulder blades with the heel of your hand, checking between each.': 'تا ۵ ضربهٔ محکم پشت میان کتف‌ها با پاشنهٔ دست بزنید و بین هر کدام بررسی کنید.',
  'Not cleared: turn the baby face up (still head-down along your arm/thigh) and give up to 5 chest thrusts on the lower half of the breastbone, just below the nipple line — two fingers, two thumbs, or the heel of one hand are all currently taught; use whichever you know.': 'باز نشد: نوزاد را به پشت برگردانید (همچنان سر پایین در امتداد ساعد/ران) و تا ۵ فشار قفسهٔ سینه روی نیمهٔ پایینی جناغ، درست زیر خط نوک پستان‌ها بدهید — دو انگشت، دو شست یا پاشنهٔ یک دست، همگی اکنون آموزش داده می‌شوند؛ از آنچه می‌دانید استفاده کنید.',
  'Keep alternating 5 back blows with 5 chest thrusts.': '۵ ضربهٔ پشت و ۵ فشار قفسهٔ سینه را به‌نوبت ادامه دهید.',
  'If the baby becomes unresponsive: start baby CPR (above) and get emergency help.': 'اگر نوزاد بی‌پاسخ شد: احیای نوزاد را شروع کنید (بالا) و کمک اورژانسی بخواهید.',
  'Never give abdominal thrusts to a baby — real risk of internal injury.': 'هرگز به نوزاد فشار شکمی ندهید — خطر واقعی آسیب داخلی.',
  'Never do a blind finger sweep; only remove an object you can actually see.': 'هرگز کورکورانه با انگشت نکاوید؛ فقط جسمی را که واقعاً می‌بینید خارج کنید.',
  'Recovery position': 'وضعیت ریکاوری',
  'For someone unresponsive but breathing normally, with no reason to suspect CPR or serious bleeding is needed: roll them onto their side and tilt the head back slightly, so the airway stays open and fluid can drain out. Do not put them on their back.': 'برای کسی که بی‌پاسخ است اما طبیعی نفس می‌کشد و دلیلی برای شک به نیاز به احیا یا خونریزی شدید نیست: او را به پهلو بچرخانید و سر را کمی به عقب خم کنید تا راه هوایی باز بماند و مایعات بتوانند خارج شوند. او را به پشت نخوابانید.',
  'A baby: do not put them on the floor — hold them face down along your forearm, head supported and tilted a little lower than the body.': 'نوزاد: او را روی زمین نگذارید — روی شکم در امتداد ساعد نگه دارید، سر حمایت‌شده و کمی پایین‌تر از بدن.',
  'Keep watching their breathing until help arrives. Noisy, irregular or gasping breathing is a sign to treat them as not breathing and start CPR instead.': 'تا رسیدن کمک تنفس را زیر نظر داشته باشید. نفس پرصدا، نامنظم یا نفس‌نفس‌زدن نشانهٔ آن است که او را «بدون نفس» فرض کنید و احیا را شروع کنید.',
  'A pregnant woman should go on her LEFT side.': 'زن باردار باید به پهلوی چپ بخوابد.',
  'Drowning': 'غرق‌شدگی',
  'Do not swim out to them unless you are trained for water rescue — reach with a pole, branch or rope, or throw something that floats, instead.': 'به سوی او شنا نکنید مگر برای نجات در آب آموزش دیده باشید — به‌جای آن چوب، شاخه یا طناب دراز کنید یا چیزی شناور پرتاب کنید.',
  'Once they are out of the water and not breathing normally: open the airway and give a few rescue breaths (guidance ranges from 2 to 5; 5 is now the most common number taught), then continue CPR at the normal ratio (30 compressions to 2 breaths).': 'وقتی از آب بیرون آمد و طبیعی نفس نمی‌کشد: راه هوایی را باز کنید و چند تنفس نجات بدهید (راهنماها از ۲ تا ۵ متغیرند؛ ۵ اکنون رایج‌ترین عدد آموزشی است)، سپس احیا را با نسبت معمول (۳۰ فشار به ۲ تنفس) ادامه دهید.',
  'Untrained, unwilling or unable to give breaths: compression-only CPR is still far better than nothing, but breaths genuinely improve survival after drowning specifically, more than in an ordinary adult cardiac arrest — give them if you can.': 'اگر آموزش ندیده‌اید، تمایل ندارید یا نمی‌توانید تنفس بدهید: احیای فقط با فشار هنوز بسیار بهتر از هیچ است، اما تنفس‌ها به‌ویژه پس از غرق‌شدگی، بیش از ایست قلبی معمول بزرگسال، شانس بقا را واقعاً بهبود می‌دهند — اگر می‌توانید بدهید.',
  'Vomiting is common during resuscitation — be ready to roll the person onto their side and clear the mouth, then continue.': 'در حین احیا استفراغ شایع است — آماده باشید فرد را به پهلو بچرخانید، دهان را پاک کنید و ادامه دهید.',
  'Everyone who was pulled from the water unresponsive, needed rescue breaths or CPR, or has any cough, breathlessness, confusion or drowsiness afterwards must be seen at a hospital, even if they seem to recover — a delayed reaction (secondary drowning) is real.': 'هر کسی که بی‌پاسخ از آب بیرون کشیده شد، به تنفس نجات یا احیا نیاز داشت یا پس از آن سرفه، تنگی نفس، گیجی یا خواب‌آلودگی دارد باید در بیمارستان دیده شود، حتی اگر بهبود یافته به نظر برسد — واکنش تأخیری (غرق‌شدگی ثانویه) واقعی است.',
  'Recognise anaphylaxis (severe allergic reaction)': 'تشخیص آنافیلاکسی (واکنش آلرژیک شدید)',
  'Sudden breathing or circulation trouble after a food, sting or medicine: swelling of the tongue or throat, noisy or difficult breathing, a wheeze or persistent cough, a hoarse voice, difficulty swallowing, dizziness or collapse.': 'اختلال ناگهانی تنفس یا گردش خون پس از غذا، نیش یا دارو: تورم زبان یا گلو، نفس پرصدا یا دشوار، خس‌خس یا سرفهٔ مداوم، گرفتگی صدا، دشواری بلع، سرگیجه یا از پا افتادن.',
  'Often — but not always — with hives or skin swelling. A reaction can be severe with no skin signs at all.': 'اغلب — اما نه همیشه — با کهیر یا تورم پوست. واکنش می‌تواند بدون هیچ نشانهٔ پوستی شدید باشد.',
  'In babies and young children specifically: sudden pale, floppy or limp, not responding normally.': 'به‌ویژه در نوزادان و کودکان خردسال: رنگ‌پریدگی ناگهانی، سستی یا بی‌حالی، پاسخ‌ندادن طبیعی.',
  'Anaphylaxis — what to do': 'آنافیلاکسی — چه کنیم',
  'If an adrenaline (epinephrine) auto-injector is available, use it AT ONCE into the outer mid-thigh — through clothing is fine.': 'اگر خودتزریق آدرنالین (اپی‌نفرین) در دسترس است، همان لحظه آن را در میانهٔ بیرونی ران بزنید — از روی لباس هم اشکالی ندارد.',
  'Call the emergency number straight away.': 'بلافاصله با شمارهٔ اضطراری تماس بگیرید.',
  'Lie the person flat and raise their legs; if breathing is very hard, let them sit up instead. Someone pregnant should lie on her left side.': 'فرد را صاف بخوابانید و پاهایش را بالا ببرید؛ اگر نفس‌کشیدن بسیار دشوار است بگذارید به‌جای آن بنشیند. زن باردار باید به پهلوی چپ بخوابد.',
  'Do not let them stand or walk, even once they feel better — a sudden drop in blood pressure while upright can be fatal.': 'نگذارید بایستد یا راه برود، حتی وقتی احساس بهتری دارد — افت ناگهانی فشار خون در حالت ایستاده می‌تواند کشنده باشد.',
  'No improvement after about 5 minutes and a second auto-injector is available: give the second dose.': 'پس از حدود ۵ دقیقه بهبودی نیست و خودتزریق دوم در دسترس است: دوز دوم را بزنید.',
  'Go to hospital every time, even after a full recovery — symptoms can return hours later (a biphasic reaction).': 'هر بار به بیمارستان بروید، حتی پس از بهبودی کامل — علائم ممکن است ساعاتی بعد برگردند (واکنش دوفازی).',
  'If in genuine doubt whether it is anaphylaxis, every source agrees: give the adrenaline. The risk of a dose given when it was not strictly needed is far smaller than the risk of withholding it when it was.': 'اگر واقعاً شک دارید که آنافیلاکسی است یا نه، همهٔ منابع هم‌نظرند: آدرنالین بزنید. خطر دوزی که بی‌نیاز زده شود بسیار کمتر از خطر دریغ‌کردن آن در زمان نیاز است.',
  'Anaphylaxis in babies and children': 'آنافیلاکسی در نوزادان و کودکان',
  'Lay a baby or toddler flat — never hold them upright.': 'نوزاد یا نوپا را صاف بخوابانید — هرگز او را ایستاده نگه ندارید.',
  'Use their own prescribed auto-injector at its prescribed dose the moment anaphylaxis is suspected.': 'به‌محض شک به آنافیلاکسی از خودتزریق تجویزشدهٔ خود کودک با دوز تجویزشده استفاده کنید.',
  'Auto-injector doses run roughly: 0.1 mg for about 7.5–15 kg (where that device exists), 0.15 mg from about 7.5–20 kg up to 30 kg depending on country and device, 0.3 mg above about 20–30 kg.': 'دوزهای خودتزریق تقریباً چنین است: ۰٫۱ میلی‌گرم برای حدود ۷٫۵ تا ۱۵ کیلوگرم (جایی که چنین دستگاهی هست)، ۰٫۱۵ میلی‌گرم از حدود ۷٫۵ تا ۲۰ کیلوگرم تا ۳۰ کیلوگرم بسته به کشور و دستگاه، ۰٫۳ میلی‌گرم بالای حدود ۲۰ تا ۳۰ کیلوگرم.',
  'Under about 7.5 kg, or any child with no prescribed device: call the emergency number immediately and let paramedics or a doctor decide the dose — do not improvise with a mismatched adult device.': 'زیر حدود ۷٫۵ کیلوگرم، یا هر کودکی که دستگاه تجویزشده ندارد: فوراً با شمارهٔ اضطراری تماس بگیرید و بگذارید امدادگران یا پزشک دوز را تعیین کنند — با دستگاه ناسازگار بزرگسال بداهه‌عمل نکنید.',
  'Dosing bands genuinely differ between countries and auto-injector brands — this is not a single fixed number worldwide. Always follow the child’s own prescribed device and plan where one exists.': 'بازه‌های دوز میان کشورها و برندهای خودتزریق واقعاً متفاوت است — یک عدد ثابت جهانی نیست. همیشه از دستگاه و برنامهٔ تجویزشدهٔ خود کودک، در صورت وجود، پیروی کنید.',
  'Asthma attack': 'حملهٔ آسم',
  'Help them sit upright — never lie them down. Stay calm; anxiety worsens breathing.': 'کمک کنید راست بنشیند — هرگز او را نخوابانید. آرام بمانید؛ اضطراب تنفس را بدتر می‌کند.',
  'Use the blue/grey reliever inhaler at once, with a spacer if one is available.': 'بلافاصله از اسپری تسکین‌دهندهٔ آبی/خاکستری استفاده کنید، در صورت وجود با اسپیسر.',
  'They have their own written asthma action plan: follow its dosing exactly.': 'اگر طرح عمل کتبی آسم دارند: دقیقاً دوزهای آن را رعایت کنید.',
  'No plan: either recognised approach is safe — 1 puff every 30–60 seconds up to 10 puffs (UK-style), or 4 puffs (one at a time via a spacer, 4 breaths each), wait 4 minutes, then repeat (Australia-style).': 'بدون طرح: هر دو رویکرد شناخته‌شده ایمن است — یک پاف هر ۳۰ تا ۶۰ ثانیه تا ۱۰ پاف (سبک بریتانیایی)، یا ۴ پاف (هر بار یکی از طریق اسپیسر، ۴ نفس برای هر کدام)، ۴ دقیقه صبر و تکرار (سبک استرالیایی).',
  'Call the emergency number if: there is no inhaler, the inhaler is not helping, lips or fingers turn blue, the person is exhausted or confused, breathing becomes quiet or slow, or symptoms have not resolved after the full first round.': 'در این موارد با شمارهٔ اضطراری تماس بگیرید: اسپری نیست، اسپری کمک نمی‌کند، لب‌ها یا انگشتان کبود می‌شوند، فرد خسته یا گیج است، تنفس آرام یا کند می‌شود، یا علائم پس از دور کامل اول برطرف نشده است.',
  'Severe bleeding': 'خونریزی شدید',
  'Apply firm, continuous direct pressure over the wound with whatever is available — a cloth, clothing, your hand.': 'با هر چیزی که در دسترس است — پارچه، لباس، دست خود — فشار مستقیم، محکم و پیوسته روی زخم وارد کنید.',
  'Life-threatening limb bleeding not controlled by pressure: apply a tourniquet a few centimetres above the wound — never over a joint — and tighten until the bleeding stops. Note the exact time it went on and do not loosen it.': 'خونریزی تهدیدکنندهٔ جان در اندام که با فشار مهار نمی‌شود: چند سانتی‌متر بالای زخم تورنیکه ببندید — هرگز روی مفصل — و آن‌قدر سفت کنید که خونریزی بایستد. زمان دقیق بستن را یادداشت کنید و آن را شل نکنید.',
  'A deep wound somewhere a tourniquet cannot go (neck, groin, armpit): pack the wound firmly and press.': 'زخم عمیق در جایی که تورنیکه نمی‌رسد (گردن، کشاله، زیر بغل): زخم را محکم پر کنید و فشار دهید.',
  'Call the emergency number for any severe bleeding.': 'برای هر خونریزی شدید با شمارهٔ اضطراری تماس بگیرید.',
  'A proper manufactured tourniquet is best; sources genuinely disagree on improvising one from a belt or scarf as a last resort — most say it is better than nothing for life-threatening limb bleeding, one major source (Mayo Clinic) advises against it. If a limb is bleeding life-threateningly and nothing manufactured exists, an improvised tourniquet — a firm, wide band tightened with a rigid object — is the safer choice for most authorities.': 'تورنیکهٔ ساخت کارخانه بهترین است؛ منابع دربارهٔ بداهه‌ساختن آن از کمربند یا روسری به‌عنوان آخرین چاره واقعاً اختلاف دارند — بیشتر می‌گویند در خونریزی تهدیدکنندهٔ جان اندام بهتر از هیچ است، یک منبع بزرگ (مایو کلینیک) توصیه نمی‌کند. اگر اندامی تهدیدکننده خونریزی می‌کند و تورنیکهٔ ساخت کارخانه نیست، تورنیکهٔ بداهه — نواری پهن و محکم که با جسمی سفت تنگ می‌شود — برای بیشتر مراجع انتخاب ایمن‌تری است.',
  'Shock': 'شوک',
  'Signs: pale, cold, clammy skin, rapid weak pulse, rapid shallow breathing, confusion or weakness.': 'نشانه‌ها: پوست رنگ‌پریده، سرد و چسبناک، نبض سریع و ضعیف، تنفس سریع و سطحی، گیجی یا ضعف.',
  'Treat the visible cause (e.g. control any bleeding).': 'علت مشهود را درمان کنید (مثلاً هر خونریزی را مهار کنید).',
  'Lie the person down; raise their legs if there is no injury (a leg fracture or suspected spinal injury) that raising them would make worse.': 'فرد را بخوابانید؛ اگر آسیبی (شکستگی پا یا مشکوک به آسیب ستون فقرات) نیست که بالا بردن پاها آن را بدتر کند، پاهایش را بالا ببرید.',
  'Keep them warm, loosen tight clothing, give nothing to eat or drink.': 'او را گرم نگه دارید، لباس تنگ را شل کنید و چیزی برای خوردن یا نوشیدن ندهید.',
  'Call the emergency number.': 'با شمارهٔ اضطراری تماس بگیرید.',
  'Burns and scalds': 'سوختگی و آب‌جوش‌زدگی',
  'Cool with cool (not ice-cold) running water for 20 minutes, starting as soon as possible — still worth doing up to about 3 hours after the burn.': 'به مدت ۲۰ دقیقه با آب جاری خنک (نه یخی) سرد کنید، هرچه زودتر شروع کنید — تا حدود ۳ ساعت پس از سوختگی همچنان ارزش دارد.',
  'Remove jewellery and clothing near the burn unless it is stuck to the skin.': 'جواهرات و لباس نزدیک سوختگی را درآورید مگر به پوست چسبیده باشند.',
  'Cover loosely with cling film (not wrapped tightly around a limb) or a clean, non-fluffy dressing.': 'آزادانه با سلفون (نه سفت دور اندام) یا پانسمان تمیز و بدون پرز بپوشانید.',
  'Chemical burn: flush continuously with plenty of water.': 'سوختگی شیمیایی: پیوسته با مقدار فراوان آب بشویید.',
  'See a doctor for: a burn larger than the person’s palm; on the face, hands, feet, genitals or a major joint; any blistering burn in a baby or young child; or any electrical or chemical burn.': 'در این موارد به پزشک مراجعه کنید: سوختگی بزرگ‌تر از کف دست فرد؛ روی صورت، دست‌ها، پاها، اندام تناسلی یا مفصل بزرگ؛ هر سوختگی تاول‌دار در نوزاد یا کودک خردسال؛ یا هر سوختگی الکتریکی یا شیمیایی.',
  'No ice, butter, toothpaste, creams or oils.': 'بدون یخ، کره، خمیردندان، کرم یا روغن.',
  'Do not burst blisters.': 'تاول‌ها را نترکانید.',
  'Heat exhaustion and heat stroke': 'گرمازدگی خفیف و گرمازدگی شدید',
  'Heat stroke — confusion, agitation, drowsiness, collapse, hot skin that has STOPPED sweating, seizures: this is a medical emergency. Call for help and start cooling immediately.': 'گرمازدگی شدید — گیجی، بی‌قراری، خواب‌آلودگی، از پا افتادن، پوست داغ که دیگر عرق نمی‌کند، تشنج: این یک اورژانس پزشکی است. کمک بخواهید و فوراً خنک‌سازی را شروع کنید.',
  'Whole-body cold-water immersion (up to the neck) is the fastest method if available. If not: pour or soak with cold water and fan the person, with ice packs at the neck, armpits and groin.': 'غوطه‌وری تمام بدن در آب سرد (تا گردن) در صورت امکان سریع‌ترین روش است. وگرنه: آب سرد بریزید یا خیس کنید و باد بزنید، با کیسهٔ یخ روی گردن، زیر بغل و کشاله.',
  'Do not give anything to drink if the person is confused or not fully alert.': 'اگر فرد گیج یا کاملاً هوشیار نیست چیزی برای نوشیدن ندهید.',
  'Heat exhaustion (milder — heavy sweating, tiredness, headache, nausea, still alert): move to shade, cool the skin, sip water or an oral rehydration/sports drink.': 'گرمازدگی خفیف (ملایم‌تر — عرق فراوان، خستگی، سردرد، تهوع، همچنان هوشیار): به سایه بروید، پوست را خنک کنید، جرعه‌جرعه آب یا نوشیدنی بازآبرسانی/ورزشی بنوشید.',
  'Seizure (fit)': 'تشنج (حملهٔ صرع)',
  'Protect them from injury — move hazards away; do not move the person unless they are somewhere dangerous.': 'از آسیب محافظتش کنید — خطرها را دور کنید؛ فرد را جابه‌جا نکنید مگر در جای خطرناکی باشد.',
  'Cushion the head; do not restrain them; put nothing in the mouth.': 'زیر سر بالشتک بگذارید؛ مهارش نکنید؛ چیزی در دهانش نگذارید.',
  'Time the seizure.': 'مدت تشنج را زمان‌گیری کنید.',
  'Once the jerking stops, place them in the recovery position (above).': 'وقتی تکان‌ها قطع شد او را در وضعیت ریکاوری (بالا) قرار دهید.',
  'Call the emergency number if: it lasts longer than 5 minutes, it repeats, it is their first ever seizure, they are injured, in water, pregnant, diabetic, or not waking up afterwards.': 'در این موارد با شمارهٔ اضطراری تماس بگیرید: بیش از ۵ دقیقه طول بکشد، تکرار شود، اولین تشنج زندگی‌اش باشد، آسیب ببیند، در آب باشد، باردار یا دیابتی باشد، یا پس از آن بیدار نشود.',
  'Febrile seizures in young children: same basic first aid — never put the child in a cold bath or undress them to bring a fever down.': 'تشنج ناشی از تب در کودکان خردسال: همان کمک‌های اولیهٔ پایه — هرگز کودک را در وان سرد نگذارید و برای پایین آوردن تب لباسش را درنیاورید.',
  'Head or neck injury, road crash': 'آسیب سر یا گردن، تصادف جاده‌ای',
  'Do not move the person unless they are in immediate danger. Keep the head and neck as still as possible.': 'فرد را جابه‌جا نکنید مگر در خطر فوری باشد. سر و گردن را تا حد ممکن بی‌حرکت نگه دارید.',
  'A motorcycle helmet: leave it on unless you need to remove it to clear the airway or because they are not breathing.': 'کلاه موتورسواری: روی سر بماند مگر لازم باشد برای باز کردن راه هوایی یا به‌دلیل نفس‌نکشیدن درآورده شود.',
  'Get to hospital for: repeated vomiting, increasing drowsiness or confusion, a worsening or persistent severe headache, a seizure, clear or blood-stained fluid from the nose or ears, or unequal pupil size.': 'در این موارد به بیمارستان بروید: استفراغ مکرر، خواب‌آلودگی یا گیجی فزاینده، سردرد شدید رو‌به‌بدتر یا پایدار، تشنج، ترشح شفاف یا خونی از بینی یا گوش، یا نابرابری مردمک‌ها.',
  'Heart attack': 'حملهٔ قلبی',
  'Call the emergency number — do not delay this to find aspirin or for any other reason.': 'با شمارهٔ اضطراری تماس بگیرید — برای یافتن آسپیرین یا هر دلیل دیگری تأخیر نکنید.',
  'Help the person sit down and rest in a comfortable position.': 'به فرد کمک کنید بنشیند و در وضعیت راحتی استراحت کند.',
  'If they are not allergic to aspirin, have no bleeding disorder, and have not already taken a full dose: have them chew an aspirin while waiting for help (chew a dose in the 150–500 mg range — 300 mg is standard in the UK, 162–325 mg in the US).': 'اگر به آسپیرین آلرژی ندارد، اختلال خونریزی ندارد و پیش‌تر دوز کامل مصرف نکرده است: از او بخواهید تا رسیدن کمک یک آسپیرین بجود (یک دوز در محدودهٔ ۱۵۰ تا ۵۰۰ میلی‌گرم بجوید — ۳۰۰ میلی‌گرم در بریتانیا و ۱۶۲ تا ۳۲۵ در آمریکا استاندارد است).',
  'Stroke — FAST': 'سکتهٔ مغزی — FAST',
  'F — Face: has one side dropped?': 'F — صورت: آیا یک طرف افتاده است؟',
  'A — Arms: can they raise both, or does one drift down?': 'A — بازوها: آیا هر دو را بالا می‌برد یا یکی پایین می‌افتد؟',
  'S — Speech: is it slurred, or can they not speak?': 'S — گفتار: آیا نامفهوم است یا نمی‌تواند حرف بزند؟',
  'T — Time: if any of these, call the emergency number immediately and note the exact time symptoms started — treatment is time-critical.': 'T — زمان: اگر هر یک از اینها بود فوراً با شمارهٔ اضطراری تماس بگیرید و زمان دقیق شروع علائم را یادداشت کنید — درمان به زمان وابسته است.',
  '(Some guidance uses "BE FAST", adding Balance and Eyes — a strokes affecting balance or vision can be missed by the classic FAST test alone.)': '(برخی راهنماها از «BE FAST» استفاده می‌کنند و تعادل و چشم‌ها را می‌افزایند — سکته‌ای که تعادل یا بینایی را مختل کند ممکن است با آزمون کلاسیک FAST به‌تنهایی تشخیص داده نشود.)',
  'Give nothing by mouth — food, drink or medicine — until swallowing has been medically checked.': 'چیزی از راه دهان ندهید — غذا، نوشیدنی یا دارو — تا بلع از نظر پزشکی بررسی شود.',
  'Low blood sugar (hypoglycaemia)': 'قند خون پایین (هیپوگلیسمی)',
  'Conscious and able to swallow: give 15–20 g of fast-acting sugar — glucose tablets, a sugary (not diet) drink, or sweets.': 'هوشیار و قادر به بلع: ۱۵ تا ۲۰ گرم قند سریع‌الاثر بدهید — قرص گلوکز، نوشیدنی شیرین (نه رژیمی) یا شیرینی.',
  'Recheck after 10–15 minutes and repeat if still low; once recovered, follow with a slower-acting snack.': 'پس از ۱۰ تا ۱۵ دقیقه دوباره بررسی کنید و اگر هنوز پایین است تکرار کنید؛ پس از بهبود، میان‌وعدهٔ کندتأثیر بدهید.',
  'Drowsy, confused or unconscious: give nothing by mouth (choking risk), put them in the recovery position, and call the emergency number. Give glucagon if one is available and you are trained to use it.': 'خواب‌آلود، گیج یا بیهوش: چیزی از راه دهان ندهید (خطر خفگی)، در وضعیت ریکاوری قرار دهید و با شمارهٔ اضطراری تماس بگیرید. اگر گلوکاگون هست و آموزش استفاده دارید بزنید.',
  'When a child’s fever needs same-day care': 'چه وقت تب کودک به مراقبت همان روز نیاز دارد',
  'Under 3 months old with a temperature of 38°C (100.4°F) or higher: same-day medical assessment, even if the baby seems otherwise well.': 'زیر ۳ ماه با دمای ۳۸ درجهٔ سانتی‌گراد (۱۰۰٫۴ فارنهایت) یا بیشتر: ارزیابی پزشکی همان روز، حتی اگر نوزاد از جهات دیگر خوب به نظر برسد.',
  '3–6 months old with a temperature of 39°C (102.2°F) or higher: get medical advice the same day.': '۳ تا ۶ ماه با دمای ۳۹ درجهٔ سانتی‌گراد (۱۰۲٫۲ فارنهایت) یا بیشتر: همان روز مشورت پزشکی بگیرید.',
  'A child’s appearance and behaviour matter as much as the exact number — treat any of the red-flag signs below as urgent regardless of the reading on the thermometer.': 'ظاهر و رفتار کودک به اندازهٔ عدد دقیق اهمیت دارد — هر یک از نشانه‌های خطر زیر را بدون توجه به عدد دماسنج فوری بدانید.',
  'Red flags in a baby or child — get emergency care now': 'نشانه‌های خطر در نوزاد یا کودک — همین حالا مراقبت اورژانسی بگیرید',
  'Does not respond normally, is very hard to wake, or is floppy.': 'به‌طور معمول پاسخ نمی‌دهد، بیدار کردنش بسیار دشوار است یا بی‌حال و شل است.',
  'Blue, grey, very pale or blotchy skin or lips.': 'پوست یا لب‌های کبود، خاکستری، بسیار رنگ‌پریده یا لکه‌لکه.',
  'Struggling to breathe — grunting, sucking in around the ribs, or pauses in breathing.': 'به‌سختی نفس می‌کشد — ناله، فرورفتن پوست دور دنده‌ها یا وقفه در تنفس.',
  'A rash that does not fade when a glass is pressed against it.': 'بثوری که با فشار دادن یک لیوان شیشه‌ای روی آن محو نمی‌شود.',
  'A fit or seizure.': 'تشنج یا حملهٔ صرع.',
  'Signs of dehydration: sunken eyes, no tears, dry mouth, very few wet nappies, a sunken soft spot.': 'نشانه‌های کم‌آبی: چشم‌های گودرفته، نبود اشک، دهان خشک، پوشک خیس بسیار کم، ملاج فرورفته.',
  'A bulging soft spot (fontanelle), a stiff neck, or a high-pitched, weak or continuous cry.': 'ملاج برآمده (فونتانل)، گردن سفت، یا گریهٔ زیر، ضعیف یا مداوم.',
  'Diarrhoea, vomiting & dehydration': 'اسهال، استفراغ و کم‌آبی',
  'Give oral rehydration solution (ORS) in small, frequent sips. Keep breastfeeding or feeding as normal.': 'محلول بازآبرسانی خوراکی (ORS) را به‌صورت جرعه‌های کوچک و مکرر بدهید. شیردهی یا تغذیه را مثل معمول ادامه دهید.',
  'No ORS packet available: 6 level teaspoons of sugar and half a level teaspoon of salt, dissolved in 1 litre of clean water — measure the salt carefully, too much can be harmful.': 'بستهٔ ORS در دسترس نیست: ۶ قاشق چای‌خوری سطح شکر و نیم قاشق چای‌خوری سطح نمک، حل‌شده در ۱ لیتر آب تمیز — نمک را با دقت اندازه بگیرید، زیاده‌روی می‌تواند مضر باشد.',
  'Zinc supplementation, where advised: 10 mg/day under 6 months, 20 mg/day over 6 months, for 10–14 days.': 'مکمل روی، در صورت توصیه: ۱۰ میلی‌گرم در روز زیر ۶ ماه، ۲۰ میلی‌گرم در روز بالای ۶ ماه، به مدت ۱۰ تا ۱۴ روز.',
  'Seek urgent care if the child cannot keep fluids down, passes little or no urine, or shows any of the red-flag signs above.': 'اگر کودک نمی‌تواند مایعات را نگه دارد، ادرار کم یا هیچ دارد یا هر یک از نشانه‌های خطر بالا را نشان می‌دهد، مراقبت فوری بگیرید.',
  'Do not give anti-diarrhoea medicine such as loperamide to a child under 12 without a doctor’s advice, and never to a child who is unwell, dehydrated, or has bloody diarrhoea.': 'به کودک زیر ۱۲ سال بدون نظر پزشک داروی ضداسهال مانند لوپرامید ندهید و هرگز به کودکی که حالش بد است، کم‌آب است یا اسهال خونی دارد ندهید.',
  'Giving a child paracetamol or ibuprofen': 'دادن پاراستامول یا ایبوپروفن به کودک',
  'Dose strictly by your child’s weight, following the pack or a doctor/pharmacist’s instructions.': 'دوز را کاملاً بر اساس وزن کودک و طبق بسته‌بندی یا دستور پزشک/داروساز تنظیم کنید.',
  'Do not give ibuprofen to a baby under 6 months, unless a doctor has said to (some guidance allows it from 3 months if the baby weighs at least 5 kg — check the product).': 'به نوزاد زیر ۶ ماه ایبوپروفن ندهید مگر پزشک گفته باشد (برخی راهنماها از ۳ ماهگی اجازه می‌دهند اگر وزن نوزاد دست‌کم ۵ کیلوگرم باشد — محصول را بررسی کنید).',
  'Never give aspirin to anyone under 19 unless a doctor specifically prescribes it — the risk is Reye’s syndrome.': 'به هیچ‌کس زیر ۱۹ سال آسپیرین ندهید مگر پزشک صراحتاً تجویز کرده باشد — خطر آن سندرم ری است.',
  'If dengue is a possibility: paracetamol only — never ibuprofen or aspirin, because of bleeding risk.': 'اگر احتمال دنگی هست: فقط پاراستامول — هرگز ایبوپروفن یا آسپیرین، به‌دلیل خطر خونریزی.',
  'Dengue warning signs': 'نشانه‌های هشدار دنگی',
  'Watch especially as a fever comes down (usually 24–48 hours after it breaks, around days 3–7 of illness) for: severe stomach pain, repeated vomiting (3 or more times in 24 hours), bleeding gums or nose, blood in vomit or stool, extreme tiredness, restlessness or irritability, rapid breathing, cold or clammy skin.': 'به‌ویژه هنگام فروکش تب (معمولاً ۲۴ تا ۴۸ ساعت پس از قطع تب، حدود روزهای ۳ تا ۷ بیماری) مراقب این موارد باشید: درد شدید معده، استفراغ مکرر (۳ بار یا بیشتر در ۲۴ ساعت)، خونریزی لثه یا بینی، خون در استفراغ یا مدفوع، خستگی شدید، بی‌قراری یا تحریک‌پذیری، تنفس سریع، پوست سرد یا چسبناک.',
  'Any one of these means urgent medical care now.': 'هر یک از این‌ها یعنی مراقبت پزشکی فوری همین حالا.',
  'While waiting: paracetamol only, and keep the person drinking fluids.': 'در حین انتظار: فقط پاراستامول و فرد را به نوشیدن مایعات ادامه دهید.',
  'Babies and young children are at extra risk of severe dengue.': 'نوزادان و کودکان خردسال در معرض خطر بیشتر دنگی شدید هستند.',
  'A child swallows something poisonous': 'کودک چیزی سمی می‌بلعد',
  'Do not make them vomit.': 'او را وادار به استفراغ نکنید.',
  'Call the emergency number, or Thailand’s Ramathibodi Poison Center (1367, 24/7), and bring the container or packaging with you.': 'با شمارهٔ اضطراری یا مرکز مسمومیت راماتیبودی تایلند (۱۳۶۷، شبانه‌روزی) تماس بگیرید و ظرف یا بسته‌بندی را همراه ببرید.',
  'A swallowed button battery is an emergency: go straight to hospital, do not wait.': 'بلعیدن باتری دکمه‌ای اورژانس است: مستقیم به بیمارستان بروید، منتظر نمانید.',
  'Over 1 year old, and the battery was swallowed within the last 12 hours, and the child can swallow normally: 10 mL (2 teaspoons) of honey by mouth every 10 minutes, up to 6 doses, on the way to hospital — this must never delay getting there.': 'بالای یک سال، و باتری در ۱۲ ساعت گذشته بلعیده شده و کودک طبیعی می‌تواند ببلعد: ۱۰ میلی‌لیتر (۲ قاشق چای‌خوری) عسل خوراکی هر ۱۰ دقیقه، تا ۶ دوز، در مسیر بیمارستان — این هرگز نباید رسیدن را به تأخیر بیندازد.',
  'Never give honey to a child under 1 year — botulism risk.': 'هرگز به کودک زیر یک سال عسل ندهید — خطر بوتولیسم.',
  'Water safety for children': 'ایمنی کودکان در آب',
  'Constant, within-arm’s-reach supervision by one sober adult with no other task, whenever a child is in, on or near any water — pool, sea, river, even a bath.': 'نظارت پیوسته، در فاصلهٔ دسترسی دست، از سوی یک بزرگسال هشیار که کار دیگری ندارد، هر زمان کودک در، روی یا نزدیک هر آبی است — استخر، دریا، رودخانه، حتی وان.',
  'A properly fitted, approved child life jacket on boats or in open water.': 'جلیقهٔ نجات تأییدشدهٔ کودک که درست اندازه شده باشد، در قایق‌ها یا آب‌های آزاد.',
  'Drowning is fast and silent, not splashy — it can happen in seconds with no cry for help.': 'غرق‌شدگی سریع و بی‌صداست، نه پرچلپ‌چلوپ — ممکن است در چند ثانیه و بدون فریاد کمک رخ دهد.',
  'Sun and heat with a baby': 'آفتاب و گرما با نوزاد',
  'Keep babies under 6 months out of direct sun — shade, an umbrella or the stroller canopy, and light clothing are the main protection.': 'نوزادان زیر ۶ ماه را از آفتاب مستقیم دور نگه دارید — سایه، چتر یا سایبان کالسکه و لباس سبک محافظت اصلی است.',
  'If shade or clothing genuinely is not possible, a small amount of sunscreen on exposed skin such as the face is acceptable under 6 months.': 'اگر سایه یا لباس واقعاً ممکن نیست، مقدار کمی ضدآفتاب روی پوست در معرض مانند صورت زیر ۶ ماه قابل‌قبول است.',
  'Exclusively breastfed babies under 6 months do not need extra water, even in heat. Formula-fed babies may be given small amounts of cooled boiled water between feeds in hot weather.': 'نوزادان زیر ۶ ماه که فقط با شیر مادر تغذیه می‌شوند حتی در گرما به آب اضافه نیاز ندارند. نوزادان شیر خشکی در هوای گرم می‌توانند میان وعده‌ها مقدار کمی آب جوشیدهٔ خنک‌شده بگیرند.',
  'Watch for: fewer wet nappies, dark urine, dry mouth, no tears, unusual sleepiness or fussiness, hot/flushed skin — get medical help if these appear.': 'مراقب این موارد باشید: پوشک خیس کمتر، ادرار تیره، دهان خشک، نبود اشک، خواب‌آلودگی یا بهانه‌گیری غیرعادی، پوست داغ/برافروخته — در صورت بروز، کمک پزشکی بگیرید.',
  'Mosquito repellent for babies and children': 'حشره‌کش برای نوزادان و کودکان',
  'Under 2 months: no repellent at all — use a mosquito net over the cot or stroller, screened rooms and covering clothing instead.': 'زیر ۲ ماه: هیچ دورکننده‌ای استفاده نکنید — به‌جای آن از پشه‌بند روی گهواره یا کالسکه، اتاق‌های دارای توری و لباس پوشاننده استفاده کنید.',
  'From 2 months: DEET up to 30% or picaridin are safe and effective (some countries, e.g. Canada, are more conservative and cap DEET at 10% for young children — check local guidance).': 'از ۲ ماهگی: دیت (DEET) تا ۳۰٪ یا پیکاریدین ایمن و مؤثر است (برخی کشورها، مثلاً کانادا، محافظه‌کارتر هستند و DEET را برای کودکان خردسال به ۱۰٪ محدود می‌کنند — راهنمای محلی را بررسی کنید).',
  'No oil of lemon eucalyptus (PMD) under 3 years.': 'روغن اکالیپتوس لیمویی (PMD) زیر ۳ سال استفاده نشود.',
  'Apply to your own hands first, then to the child’s face, avoiding eyes and mouth — or apply to clothing instead. Avoid the child’s hands.': 'ابتدا روی دست‌های خودتان بمالید، سپس روی صورت کودک، با پرهیز از چشم و دهان — یا به‌جای آن روی لباس بزنید. از دست‌های کودک دوری کنید.',
  'Snake bite': 'نیش مار',
  'Move away from the snake. Keep the person calm and lying as still as possible — movement and panic speed venom through the body.': 'از مار دور شوید. فرد را آرام و تا حد ممکن بی‌حرکت خوابیده نگه دارید — حرکت و وحشت سم را در بدن سریع‌تر پخش می‌کنند.',
  'Immobilise the bitten limb with a splint or sling. Remove rings, watches and tight clothing before swelling starts.': 'اندام گزیده‌شده را با آتل یا آویز بی‌حرکت کنید. پیش از شروع تورم، انگشتر، ساعت و لباس تنگ را درآورید.',
  'Get to a hospital that can give antivenom as fast as possible.': 'هرچه سریع‌تر به بیمارستانی بروید که پادزهر دارد.',
  'If trained in it: a firm pressure bandage over the whole limb (pressure-immobilisation), plus the splint, is the preferred field technique in this region when the snake cannot be identified — but only if you know how, and never at the cost of delaying transport.': 'اگر آموزش دیده‌اید: بانداژ فشاری محکم روی کل اندام (بی‌حرکت‌سازی با فشار) به‌همراه آتل، روش میدانی ترجیحی در این منطقه است وقتی مار قابل شناسایی نیست — اما فقط اگر بلدید و هرگز به بهای تأخیر در انتقال.',
  'Paracetamol, not aspirin or NSAIDs, if pain relief is needed — NSAIDs can worsen bleeding.': 'در صورت نیاز به مسکن، پاراستامول، نه آسپیرین یا NSAIDها — NSAIDها می‌توانند خونریزی را بدتر کنند.',
  'Do not cut the wound or try to suck out venom.': 'زخم را نبرید و سعی نکنید سم را بمکید.',
  'Do not apply a tight tourniquet, ice, an electric shock, alcohol or herbal remedies.': 'تورنیکهٔ سفت، یخ، شوک الکتریکی، الکل یا داروهای گیاهی به کار نبرید.',
  'Do not try to catch or kill the snake — a photo from a safe distance is fine, but never delay travel to identify it.': 'سعی نکنید مار را بگیرید یا بکشید — عکس از فاصلهٔ امن اشکالی ندارد، اما هرگز برای شناسایی آن حرکت را به تأخیر نیندازید.',
  'Washing the wound is fine and even sensible; do not scrub it or apply anything else to it.': 'شستن زخم اشکالی ندارد و حتی منطقی است؛ آن را نسابید و چیز دیگری رویش نمالید.',
  'Jellyfish sting (including box jellyfish)': 'نیش عروس دریایی (از جمله عروس دریایی جعبه‌ای)',
  'Get out of the water.': 'از آب خارج شوید.',
  'If not breathing normally: start CPR (above) — a box jellyfish sting can be life-threatening within minutes.': 'اگر طبیعی نفس نمی‌کشد: احیا را شروع کنید (بالا) — نیش عروس دریایی جعبه‌ای می‌تواند ظرف چند دقیقه تهدیدکنندهٔ جان باشد.',
  'Pour plenty of vinegar on the sting for at least 30 seconds.': 'مقدار فراوان سرکه روی نیش دست‌کم ۳۰ ثانیه بریزید.',
  'Then remove any remaining tentacles with tweezers, a card edge, or a gloved hand — protect yourself from being stung too.': 'سپس شاخک‌های باقی‌مانده را با موچین، لبهٔ کارت یا دست دستکش‌پوش بردارید — از نیش‌خوردن خودتان جلوگیری کنید.',
  'Afterwards, for pain: either hot water or a cold pack may help — sources disagree on which is better, so use whichever is available.': 'سپس برای درد: آب گرم یا کیسهٔ سرد ممکن است کمک کند — منابع در اینکه کدام بهتر است اختلاف دارند، پس از هر کدام که در دسترس است استفاده کنید.',
  'Call the emergency number for severe pain, breathing difficulty, chest discomfort, confusion or collapse. Worse within 30 minutes → urgent care regardless.': 'در صورت درد شدید، دشواری تنفس، ناراحتی قفسهٔ سینه، گیجی یا از پا افتادن با شمارهٔ اضطراری تماس بگیرید. بدتر شدن ظرف ۳۰ دقیقه ← در هر حال مراقبت فوری.',
  'Do not rub the area.': 'ناحیه را مالش ندهید.',
  'Do not rinse with fresh water — it can trigger more stings.': 'با آب شیرین نشویید — می‌تواند نیش‌های بیشتری را فعال کند.',
  'No alcohol, and no urine.': 'بدون الکل و بدون ادرار.',
  'Stingray, stonefish or lionfish spine injury': 'آسیب خار ماهی خارپشت، ماهی سنگی یا ماهی شیر',
  'Immerse the wound in water as hot as can be comfortably tolerated without scalding (around 45°C) for roughly 20–90 minutes, or until the pain is controlled.': 'زخم را در آبی تا حد قابل‌تحمل بدون سوختگی (حدود ۴۵ درجهٔ سانتی‌گراد) حدود ۲۰ تا ۹۰ دقیقه یا تا کنترل درد غوطه‌ور کنید.',
  'Leave an embedded spine or barb in place — it may be plugging the wound — unless a medical professional tells you to remove it.': 'خار یا قلاب فرورفته را سر جایش بگذارید — ممکن است زخم را مسدود کرده باشد — مگر کادر پزشکی بگوید درآورید.',
  'Get medical care afterwards: infection risk, a possible retained fragment, antivenom (stonefish), and tetanus risk are all real.': 'پس از آن مراقبت پزشکی بگیرید: خطر عفونت، قطعهٔ باقی‌مانده، پادزهر (ماهی سنگی) و خطر کزاز همه واقعی‌اند.',
  'A sea urchin puncture is different — do NOT use the hot-water method. Wash it with soap and water instead, and seek care if a spine has gone into a joint.': 'فرو رفتن خار خارپشت دریایی متفاوت است — از روش آب گرم استفاده نکنید. به‌جای آن با آب و صابون بشویید و اگر خاری وارد مفصل شد مراقبت بگیرید.',
  'Blue-ringed octopus or cone snail': 'هشت‌پای حلقه‌آبی یا حلزون مخروطی',
  'Keep the person still and calm.': 'فرد را بی‌حرکت و آرام نگه دارید.',
  'Apply a firm pressure-immobilisation bandage over the site and along the whole limb, then splint it — the same technique used for a dangerous snake bite.': 'بانداژ فشاری بی‌حرکت‌ساز محکمی روی محل و در طول کل اندام ببندید، سپس آتل کنید — همان روشی که برای نیش مار خطرناک به کار می‌رود.',
  'Call the emergency number and get to a hospital without waiting for symptoms to appear.': 'با شمارهٔ اضطراری تماس بگیرید و بدون انتظار برای بروز علائم به بیمارستان بروید.',
  'Be ready to give rescue breaths or CPR — the venom can paralyse breathing for several hours, with no antivenom for either animal, and resuscitation must continue until professional help takes over.': 'آماده باشید تنفس نجات یا احیا بدهید — سم می‌تواند تنفس را چند ساعت فلج کند، برای هیچ‌یک از این دو جانور پادزهر نیست و احیا باید تا تحویل به نیروی حرفه‌ای ادامه یابد.',
  'Both animals are present in Thai waters (Gulf of Thailand and Andaman Sea); real encounters are rare, since both favour deeper water than most swimmers use, but the risk is severe enough to know this before it happens. Hot water does NOT help this sting (unlike a fish spine) — the toxin is heat-stable.': 'هر دو جانور در آب‌های تایلند (خلیج تایلند و دریای آندامان) وجود دارند؛ برخورد واقعی نادر است چون هر دو آب عمیق‌تر از محل شنای بیشتر شناگران را ترجیح می‌دهند، اما خطر آن‌قدر جدی است که باید پیش از رخ‌دادن بدانید. آب گرم به این نیش کمک نمی‌کند (برخلاف خار ماهی) — سم در برابر گرما پایدار است.',
  'Animal bite, scratch or lick on broken skin (rabies risk)': 'گاز گرفتن، خراش یا لیسیدن حیوان روی پوست آسیب‌دیده (خطر هاری)',
  'Wash the wound thoroughly with soap and running water for at least 15 minutes (up to 20 minutes per Thailand-specific guidance) immediately.': 'زخم را بلافاصله و به‌طور کامل با صابون و آب جاری دست‌کم ۱۵ دقیقه (طبق راهنمای ویژهٔ تایلند تا ۲۰ دقیقه) بشویید.',
  'Apply an antiseptic (povidone-iodine or alcohol) if you have it.': 'در صورت داشتن، ضدعفونی‌کننده (پووی‌دون ید یا الکل) بزنید.',
  'Get to a clinic or hospital THE SAME DAY for rabies post-exposure treatment — do not wait to see if the animal seems sick. Vaccine (and immunoglobulin, where indicated) is available at provincial and most district hospitals in Thailand.': 'همان روز برای درمان پس از مواجهه با هاری به کلینیک یا بیمارستان بروید — منتظر نشانه‌های بیماری در حیوان نمانید. واکسن (و ایمونوگلوبولین در صورت لزوم) در بیمارستان‌های استانی و بیشتر بیمارستان‌های شهرستانی تایلند موجود است.',
  'Vaccinated before the trip: you still need booster doses after a real exposure — say so at the clinic; you will need fewer doses and no immunoglobulin.': 'پیش از سفر واکسن زده‌اید: پس از مواجههٔ واقعی هنوز به دوزهای یادآور نیاز دارید — در کلینیک بگویید؛ دوز کمتر و بدون ایمونوگلوبولین لازم خواهد بود.',
  'Dogs, cats, monkeys and bats can all carry rabies across Thailand, Vietnam, Cambodia and Laos. A lick on broken skin is treated the same as a bite or scratch.': 'سگ، گربه، میمون و خفاش همگی می‌توانند در تایلند، ویتنام، کامبوج و لائوس ناقل هاری باشند. لیسیدن روی پوست آسیب‌دیده مثل گاز گرفتن یا خراش درمان می‌شود.',
  'Caught in a rip current': 'گرفتار در جریان برگشتی',
  'Do not try to swim straight back to shore against it — you will exhaust yourself.': 'سعی نکنید مستقیم برخلاف جریان به ساحل برگردید — خودتان را خسته می‌کنید.',
  'Stay calm, float or tread water, and raise an arm and call out to signal for help.': 'آرام بمانید، روی آب بمانید یا در جا شنا کنید، یک دست را بالا ببرید و برای کمک صدا بزنید.',
  'Swim parallel to the shore to escape the current, or let it carry you out until it weakens (usually just past the breaking waves) and then swim back at an angle.': 'موازی ساحل شنا کنید تا از جریان خارج شوید، یا بگذارید شما را به بیرون ببرد تا ضعیف شود (معمولاً درست آن سوی امواج شکسته) و سپس مایل به ساحل برگردید.',
  'A red flag means do not swim. Thailand’s south-west monsoon (roughly May–October) brings rough seas and dangerous rip currents, especially on Andaman (west) coast beaches — ferries and speedboats, including those serving the Trat islands, are sometimes suspended in rough weather.': 'پرچم قرمز یعنی شنا نکنید. موسمی جنوب‌غربی تایلند (تقریباً مه تا اکتبر) دریای متلاطم و جریان‌های برگشتی خطرناک می‌آورد، به‌ویژه در سواحل آندامان (غربی) — کشتی‌ها و قایق‌های تندرو، از جمله آن‌هایی که به جزایر ترات خدمت می‌دهند، گاهی در هوای ناآرام متوقف می‌شوند.',
  'Lightning': 'آذرخش',
  'Hearing thunder or seeing lightning nearby: get indoors into a substantial building, or into a hard-topped (metal-roof) vehicle with the windows up.': 'صدای رعد شنیدید یا آذرخش نزدیک دیدید: به ساختمانی محکم یا خودرویی با سقف سخت (سقف فلزی) با شیشه‌های بالا بروید.',
  'Get out of the water and off the beach at once — do not shelter under a beach pavilion, umbrella or open-sided shelter.': 'فوراً از آب و ساحل خارج شوید — زیر آلاچیق ساحلی، چتر یا سایبان بدون دیوار پناه نگیرید.',
  'Wait at least 30 minutes after the last thunderclap before going back outside.': 'دست‌کم ۳۰ دقیقه پس از آخرین رعد صبر کنید و بعد بیرون بروید.',
  'A lightning-strike victim carries no electrical charge — it is safe to touch them immediately and start CPR if they are not breathing.': 'قربانی صاعقه بار الکتریکی ندارد — لمس فوری او ایمن است و اگر نفس نمی‌کشد احیا را شروع کنید.',
  'Calling for help in Thailand — beyond the main number': 'درخواست کمک در تایلند — فراتر از شمارهٔ اصلی',
  '1669 (medical emergency/ambulance) is free from any phone, works nationwide 24 hours, and operators can usually handle basic English — say "English" as soon as the call connects. Response is markedly slower on islands and in rural areas than in Bangkok.': '۱۶۶۹ (اورژانس پزشکی/آمبولانس) از هر تلفنی رایگان است، در سراسر کشور ۲۴ ساعته کار می‌کند و اپراتورها معمولاً انگلیسی ساده را می‌فهمند — به‌محض وصل‌شدن تماس بگویید "English". پاسخ‌دهی در جزایر و مناطق روستایی به‌طور محسوسی کندتر از بانکوک است.',
  '191 is police, 199 is fire — both free and 24 hours.': '۱۹۱ پلیس و ۱۹۹ آتش‌نشانی است — هر دو رایگان و ۲۴ ساعته.',
  '1155 is the Tourist Police: a free, 24-hour hotline specifically staffed for English-speaking travellers — a good parallel or backup call, though not a replacement for 1669 in a medical emergency.': '۱۱۵۵ پلیس گردشگری است: خط ویژهٔ رایگان و ۲۴ ساعته که مخصوص مسافران انگلیسی‌زبان نیرو دارد — تماسی موازی یا پشتیبان خوب، اما جایگزین ۱۶۶۹ در اورژانس پزشکی نیست.',
  '1367 is the Ramathibodi Poison Center’s 24/7 consultation hotline.': '۱۳۶۷ خط مشاورهٔ شبانه‌روزی مرکز مسمومیت راماتیبودی است.',
  '1199 is the Marine Department’s 24-hour hotline for water incidents (boats, ferries, accidents at sea).': '۱۱۹۹ خط ویژهٔ ۲۴ ساعتهٔ اداره دریایی برای حوادث آبی (قایق‌ها، کشتی‌ها، حوادث دریایی) است.',
  'This is Thailand-specific detail underneath the country’s own main emergency number, which this app already shows at the top of the SOS and hospital screens for whichever country you are in.': 'این جزئیات ویژهٔ تایلند است، زیر شمارهٔ اضطراری اصلی خود کشور، که این برنامه پیش‌تر در بالای صفحه‌های SOS و بیمارستان برای هر کشوری که در آن هستید نشان می‌دهد.',
  'Insurance and getting evacuated': 'بیمه و تخلیه',
  'Comprehensive travel insurance covering medical treatment AND emergency evacuation (including from remote islands) is not optional here — do not assume your home healthcare system covers this.': 'بیمهٔ جامع مسافرتی که درمان پزشکی و تخلیهٔ اضطراری (از جمله از جزایر دورافتاده) را پوشش دهد در اینجا اختیاری نیست — فرض نکنید نظام سلامت کشور خودتان این را پوشش می‌دهد.',
  'Foreigners are charged for all medical treatment; there is no reciprocal free-healthcare arrangement.': 'از خارجی‌ها برای هر درمان پزشکی هزینه گرفته می‌شود؛ ترتیب متقابل برای مراقبت رایگان وجود ندارد.',
  'Private hospitals — the fastest, highest-standard option — commonly want a deposit or a formal insurer "guarantee of payment" before non-emergency treatment. Even with insurance, you may be billed as self-pay until that guarantee arrives, which can take 24–72 hours or more.': 'بیمارستان‌های خصوصی — سریع‌ترین و با بالاترین استاندارد — معمولاً پیش از درمان غیراورژانسی ودیعه یا «تضمین پرداخت» رسمی از بیمه‌گر می‌خواهند. حتی با بیمه، تا رسیدن آن تضمین ممکن است به‌عنوان پرداخت شخصی صورتحساب بگیرید که ممکن است ۲۴ تا ۷۲ ساعت یا بیشتر طول بکشد.',
  'Call your insurer’s assistance line as early as possible — ideally before admission, not after.': 'هرچه زودتر با خط پشتیبانی بیمه‌گر خود تماس بگیرید — ترجیحاً پیش از پذیرش، نه پس از آن.',
  'Malaria, dengue and Japanese encephalitis risk': 'خطر مالاریا، دنگی و انسفالیت ژاپنی',
  'Malaria in Thailand is concentrated in remote, forested border areas (with Cambodia, Myanmar and Malaysia) — the tourist islands themselves are low or negligible risk, and routine antimalarial tablets are generally not needed for an island or beach trip.': 'مالاریا در تایلند در مناطق مرزی دورافتادهٔ جنگلی (با کامبوج، میانمار و مالزی) متمرکز است — خود جزایر گردشگری خطر کم یا ناچیز دارند و معمولاً برای سفر به جزیره یا ساحل قرص ضدمالاریا لازم نیست.',
  'Dengue is different: it is endemic across Thailand, Vietnam, Cambodia and Laos, including all the islands, year-round with a rainy-season peak. There is no vaccine relied on for casual travel — bite avoidance (repellent, covering clothing, screens) is the real prevention.': 'دنگی فرق دارد: در سراسر تایلند، ویتنام، کامبوج و لائوس، از جمله همهٔ جزایر، بومی است و در تمام سال با اوج در فصل بارانی دیده می‌شود. واکسنی که برای سفر معمولی بر آن تکیه شود وجود ندارد — پرهیز از نیش پشه (دورکننده، لباس پوشاننده، توری) پیشگیری واقعی است.',
  'Japanese encephalitis occurs countrywide outside Bangkok, peaking seasonally (roughly May–October), and is weighted toward rural, rice-farming areas. Vaccination is mainly advised for longer stays (a month or more) or higher-risk itineraries.': 'انسفالیت ژاپنی در سراسر کشور خارج از بانکوک رخ می‌دهد، با اوج فصلی (تقریباً مه تا اکتبر) و بیشتر در مناطق روستایی برنج‌کاری. واکسن عمدتاً برای اقامت طولانی‌تر (یک ماه یا بیشتر) یا مسیرهای پرخطرتر توصیه می‌شود.',
  'Anyone trekking into remote forest near an international border should get individual pre-trip travel-clinic advice regardless of the above.': 'هر کسی که در جنگل دورافتاده نزدیک مرز بین‌المللی پیاده‌روی می‌کند باید پیش از سفر مشاورهٔ فردی از کلینیک طب مسافرت بگیرد، فارغ از آنچه در بالا آمد.',
};
